import type { Route } from "next";
// Generated by Next (`next typegen` / `next build`) from the app directory.
import type { AppRoutes } from "../../../.next/types/routes";

/*
 * Typed links for the website. typedRoutes checks hrefs written as literals; nav lists and helpers pass paths around as
 * values, so they use SitePath: any website route (staff and API routes left out), optionally with a #hash or ?query.
 */
type FillParams<S extends string> = S extends `${infer A}[${string}]${infer B}` ? `${A}${string}${FillParams<B>}` : S;
type SiteRoute = FillParams<Exclude<AppRoutes, `/dashboard${string}` | "/login" | `/api${string}`>>;
export type SitePath = SiteRoute | `${SiteRoute}#${string}` | `${SiteRoute}?${string}`;

export const siteHref = (path: SitePath) => path as unknown as Route;
